<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { Pencil, Trash2 } from 'lucide-vue-next'
import type { AdminGame, AdminGameInput, AdminGameSetupResponse, GamePlayer } from '@@/types/admin-club'
import type { MatchWeatherResult } from '@@/types/weather'
definePageMeta({ allowedRoles: ['admin'] })
const id = useRoute().params.id as string
const { data, pending, error: loadError, refresh } = useFetch<{ game: AdminGame, players: GamePlayer[], weather: MatchWeatherResult, weatherAttribution: { label: string, url: string } }>(`/api/admin/games/${id}`, {
  lazy: true,
  timeout: 10_000,
})
const selectedIds = ref<string[]>([]); const adding = ref(false); const deleting = ref(false); const savingResult = ref(false); const error = ref<string | null>(null)
const editing = ref(false); const savingChanges = ref(false)
type GameForm = Omit<AdminGameInput, 'matchday' | 'round_label' | 'home_score' | 'away_score' | 'notes'> & { matchday: string | number, round_label: string, home_score: string | number, away_score: string | number, notes: string }
const form = reactive<GameForm>({ team_id: '', season_id: '', competition_id: null, venue_id: null, opponent_name: '', location_type: 'home', scheduled_at: '', matchday: '', round_label: '', status: 'scheduled', home_score: 0, away_score: 0, notes: '' })
const selectClass = 'flex min-h-[44px] w-full rounded-lg border border-input bg-surface px-3 py-2 text-sm text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400'
const { data: setupData } = await useFetch<AdminGameSetupResponse>('/api/admin/games/setup', { default: () => ({ seasons: [], competitions: [], venues: [], teams: [] }) })
const setup = computed(() => setupData.value ?? { seasons: [], competitions: [], venues: [], teams: [] })
const activeTeams = computed(() => setup.value.teams.filter((item) => item.is_active || item.id === form.team_id))
const activeSeasons = computed(() => setup.value.seasons.filter((item) => item.is_active || item.id === form.season_id))
const availableCompetitions = computed(() => setup.value.competitions.filter((item) => (item.is_active || item.id === form.competition_id) && item.season_id === form.season_id))
const availableVenues = computed(() => setup.value.venues.filter((item) => item.is_active || item.id === form.venue_id))
const { data: eligibleData } = useFetch<{ players: Array<{ id: string, full_name: string, shirt_number: number | null }> }>(`/api/admin/games/${id}/eligible-players`, {
  default: () => ({ players: [] }),
  lazy: true,
  timeout: 10_000,
})
const selectedPlayerIds = computed(() => new Set(data.value?.players.map(player => player.player_id) ?? []))
async function addPlayers() { adding.value = true; error.value = null; try { await $fetch(`/api/admin/games/${id}/players`, { method: 'POST', body: { player_ids: selectedIds.value } }); selectedIds.value = []; await refresh() } catch (value) { error.value = 'Nie udało się dodać zawodników.' } finally { adding.value = false } }
async function saveResult() { if (!data.value) return; savingResult.value = true; error.value = null; try { await $fetch(`/api/admin/games/${id}`, { method: 'PATCH', body: { home_score: data.value.game.home_score, away_score: data.value.game.away_score, status: 'completed' } } as never); await refresh() } catch (value) { error.value = 'Nie udało się zapisać wyniku.' } finally { savingResult.value = false } }
function dateTimeLocal(value: string) { const date = new Date(value); const offset = date.getTimezoneOffset(); return new Date(date.getTime() - offset * 60_000).toISOString().slice(0, 16) }
function populateForm(game: AdminGame) { Object.assign(form, { team_id: game.team_id, season_id: game.season_id, competition_id: game.competition_id, venue_id: game.venue_id, opponent_name: game.opponent_name, location_type: game.location_type, scheduled_at: dateTimeLocal(game.scheduled_at), matchday: game.matchday ?? '', round_label: game.round_label ?? '', status: game.status, home_score: game.home_score, away_score: game.away_score, notes: game.notes ?? '' }) }
function startEditing() { if (!data.value) return; populateForm(data.value.game); editing.value = true; error.value = null }
function cancelEditing() { editing.value = false; error.value = null }
async function saveChanges() { savingChanges.value = true; error.value = null; try { await $fetch(`/api/admin/games/${id}`, { method: 'PATCH', body: { ...form, opponent_name: form.opponent_name.trim(), scheduled_at: new Date(form.scheduled_at).toISOString(), matchday: form.matchday === '' ? null : Number(form.matchday), round_label: form.round_label.trim() || null, home_score: Number(form.home_score), away_score: Number(form.away_score), notes: form.notes.trim() || null } } as never); await refresh(); editing.value = false } catch (value) { error.value = 'Nie udało się zapisać zmian meczu.' } finally { savingChanges.value = false } }
async function deleteGame() { if (!window.confirm('Usunąć ten mecz? Kadra i zapisy obecności również zostaną usunięte.')) return; deleting.value = true; try { await $fetch(`/api/admin/games/${id}`, { method: 'DELETE' } as never); await navigateTo('/admin/games') } catch (value) { error.value = 'Nie udało się usunąć meczu.'; deleting.value = false } }
function format(value: string) { return new Intl.DateTimeFormat('pl-PL', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) }
watch(() => form.season_id, () => { if (!availableCompetitions.value.some((item) => item.id === form.competition_id)) form.competition_id = null })
</script>
<template><div class="mx-auto max-w-4xl space-y-6"><NuxtLink to="/admin/games" class="text-sm text-brand-700">← Mecze</NuxtLink><div v-if="pending">Wczytywanie meczu...</div><p v-else-if="loadError || !data" class="rounded-lg bg-[var(--status-declined-bg)] p-4 text-sm">{{ loadError?.data?.statusMessage || 'Nie udało się wczytać meczu. Wróć do listy meczów i spróbuj ponownie.' }}</p><template v-else><div class="flex flex-wrap items-start justify-between gap-3"><div><h1>{{ data.game.team.name }} – {{ data.game.opponent_name }}</h1><p class="text-body text-[color:var(--color-text-secondary)]">{{ format(data.game.scheduled_at) }} · {{ data.game.season.name }}</p></div><div class="flex gap-2"><Button variant="outline" class="gap-2" @click="startEditing"><Pencil class="h-4 w-4" />Edytuj mecz</Button><Button variant="destructive" class="gap-2" :disabled="deleting" @click="deleteGame"><Trash2 class="h-4 w-4" />{{ deleting ? 'Usuwanie...' : 'Usuń mecz' }}</Button></div></div><div v-if="error" class="rounded-lg bg-[var(--status-declined-bg)] p-3 text-sm">{{ error }}</div><Card v-if="editing" class="space-y-4"><div><h2>Edytuj mecz</h2><p class="mt-1 text-sm text-[color:var(--color-text-secondary)]">Zmień szczegóły spotkania i zapisz aktualizację.</p></div><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="saveChanges"><div><Label for="edit-game-team">Drużyna Sporting</Label><select id="edit-game-team" v-model="form.team_id" :class="selectClass" required><option v-for="item in activeTeams" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><Label for="edit-game-season">Sezon</Label><select id="edit-game-season" v-model="form.season_id" :class="selectClass" required><option v-for="item in activeSeasons" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><Label for="edit-game-opponent">Przeciwnik</Label><Input id="edit-game-opponent" v-model="form.opponent_name" required /></div><div><Label for="edit-game-kickoff">Rozpoczęcie</Label><Input id="edit-game-kickoff" v-model="form.scheduled_at" type="datetime-local" required /></div><div><Label for="edit-game-competition">Rozgrywki</Label><select id="edit-game-competition" v-model="form.competition_id" :class="selectClass"><option :value="null">Mecz towarzyski / bez rozgrywek</option><option v-for="item in availableCompetitions" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><Label for="edit-game-venue">Miejsce</Label><select id="edit-game-venue" v-model="form.venue_id" :class="selectClass"><option :value="null">Miejsce do potwierdzenia</option><option v-for="item in availableVenues" :key="item.id" :value="item.id">{{ item.name }}{{ item.city ? ` · ${item.city}` : '' }}</option></select></div><div><Label for="edit-game-location">Lokalizacja</Label><select id="edit-game-location" v-model="form.location_type" :class="selectClass"><option value="home">U siebie</option><option value="away">Na wyjeździe</option><option value="neutral">Teren neutralny</option></select></div><div><Label for="edit-game-matchday">Kolejka</Label><Input id="edit-game-matchday" v-model="form.matchday" type="number" min="1" /></div><div><Label for="edit-game-round">Runda</Label><Input id="edit-game-round" v-model="form.round_label" /></div><div><Label for="edit-game-status">Status</Label><select id="edit-game-status" v-model="form.status" :class="selectClass"><option value="scheduled">Zaplanowany</option><option value="completed">Zakończony</option><option value="postponed">Przełożony</option><option value="cancelled">Odwołany</option></select></div><template v-if="form.status === 'completed'"><div><Label for="edit-game-home-score">Wynik gospodarzy</Label><Input id="edit-game-home-score" v-model="form.home_score" type="number" min="0" required /></div><div><Label for="edit-game-away-score">Wynik gości</Label><Input id="edit-game-away-score" v-model="form.away_score" type="number" min="0" required /></div></template><div class="sm:col-span-2"><Label for="edit-game-notes">Notatki</Label><textarea id="edit-game-notes" v-model="form.notes" class="min-h-[88px] w-full rounded-lg border border-input bg-surface px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400" /></div><div class="flex gap-3 sm:col-span-2"><Button type="submit" :disabled="savingChanges">{{ savingChanges ? 'Zapisywanie...' : 'Zapisz zmiany' }}</Button><Button type="button" variant="outline" :disabled="savingChanges" @click="cancelEditing">Anuluj</Button></div></form></Card><Card class="space-y-2"><p>Miejsce: {{ data.game.venue?.name || 'Do potwierdzenia' }}</p><p>Status: {{ data.game.status }}</p><p v-if="data.game.status === 'completed'" class="text-h2">{{ data.game.home_score }}–{{ data.game.away_score }}</p></Card><AppMatchWeatherCard v-if="data.weather.status === 'available'" :weather="data.weather" :attribution="data.weatherAttribution" /><Card v-else-if="data.weather.status === 'forecast-not-available-yet'" class="text-sm text-[color:var(--color-text-secondary)]">Prognoza pogody nie jest jeszcze dostępna.</Card><Card class="space-y-4"><div><h2>Wynik meczu</h2><p class="mt-1 text-sm text-[color:var(--color-text-secondary)]">Nowy mecz zaczyna się od wyniku 0–0. Zapisanie wyniku oznacza mecz jako zakończony.</p></div><form class="flex flex-wrap items-end gap-3" @submit.prevent="saveResult"><div><Label for="admin-home-score">Gospodarze</Label><Input id="admin-home-score" v-model.number="data.game.home_score" type="number" min="0" required /></div><span class="pb-2 text-h2">–</span><div><Label for="admin-away-score">Goście</Label><Input id="admin-away-score" v-model.number="data.game.away_score" type="number" min="0" required /></div><Button type="submit" :disabled="savingResult">{{ savingResult ? 'Zapisywanie...' : 'Zapisz wynik' }}</Button></form></Card><Card class="space-y-3"><h2>Dodaj zawodników</h2><div class="grid gap-2 sm:grid-cols-2"><label v-for="player in eligibleData?.players.filter(item => !selectedPlayerIds.has(item.id))" :key="player.id" class="flex min-h-[44px] items-center gap-3 rounded-lg border border-border px-3"><input v-model="selectedIds" type="checkbox" :value="player.id">{{ player.full_name }}</label></div><Button :disabled="adding || !selectedIds.length" @click="addPlayers">{{ adding ? 'Dodawanie...' : 'Dodaj wybranych zawodników' }}</Button></Card><Card class="overflow-hidden p-0"><div class="border-b border-border p-4"><h2>Dostępność kadry</h2></div><p v-if="!data.players.length" class="p-6 text-center text-sm">Do tego meczu nie dodano jeszcze zawodników.</p><NuxtLink v-for="player in data.players" :key="player.player_id" :to="`/admin/players/${player.player_id}`" class="flex justify-between border-b border-border p-4"><span>{{ player.player.full_name }}</span><Badge :status="player.availability_status === 'available' ? 'confirmed' : player.availability_status === 'unavailable' ? 'declined' : 'pending'">{{ player.availability_status }}</Badge></NuxtLink></Card></template></div></template>
